import java.io.*;
import java.util.*;

public class EducationalRound86E {

    private static final long MOD = 998244353L;
    private static final int MAX = 400010;
    private static long[] fact;
    private static long[] invFact;

    private static void setup() {
        fact = new long[MAX];
        invFact = new long[MAX];
        fact[0] = 1;
        invFact[0] = 1;
        for (int i = 1; i < MAX; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[MAX - 1] = modPow(fact[MAX - 1], MOD - 2);
        for (int i = MAX - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
    }

    private static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static void process() {
        setup();
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        if (k == 0) {
            System.out.println(fact[n]);
            return;
        }
        if (n <= k) {
            System.out.println(0);
            return;
        }
        long choose = nCr(n, k);
        int m = n - k;
        long sum = 0;
        for (int i = 0; i <= m; i++) {
            long term = nCr(m, i) * modPow(m - i, n) % MOD;
            if ((i & 1) == 1) {
                sum = (sum - term + MOD) % MOD;
            } else {
                sum = (sum + term) % MOD;
            }
        }
        long result = 2 * choose % MOD * sum % MOD;
        System.out.println(result);
    }

    public static void main(String[] args) {
        process();
    }
}
